interface IShape { double Area(); }

struct Square : IShape
{
    public double Side;
    public double Area() => Side * Side;
}

var s = new Square { Side = 2 };
s.Area();          // call Square::Area — no box
IShape sh = s;     // box: a copy of s moved to the heap
sh.Area();         // a call on the box through the interface

